"use client";

import { useEffect, useState } from "react";
import { useRouter, useParams } from "next/navigation";
import axios from "axios";
import { motion } from "framer-motion";
import { FaStripe } from "react-icons/fa";

export default function CheckoutPage() {
  const { productId } = useParams();
  const router = useRouter();

  const [item, setItem] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // ✅ ADDRESS STATE
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [address, setAddress] = useState("");
  const [city, setCity] = useState("");
  const [pincode, setPincode] = useState("");

  // ✅ PAYMENT MODE
  const [paymentMode, setPaymentMode] =
    useState<"cod" | "stripe">("cod");

  // ✅ FETCH ONLY SELECTED PRODUCT FROM CART
  useEffect(() => {
    const loadProduct = async () => {
      try {
        const res = await axios.get("/api/cart/get");
        const found = res.data.cart.find(
          (i: any) => i.product._id === productId
        );

        if (!found) {
          router.push("/cart");
          return;
        }

        setItem(found);

        // ❗ COD auto-disable if product doesn't support
        if (found.product.payOnDelivery === false) {
          setPaymentMode("stripe");
        }
      } catch (err) {
        console.log("Checkout load error", err);
      } finally {
        setLoading(false);
      }
    };

    loadProduct();
  }, [productId, router]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-black text-white">
        Loading Checkout...
      </div>
    );
  }

  if (!item) return null;

  // ✅ AMOUNT CALCULATION (SINGLE PRODUCT)
  const productsTotal =
    item.product.price * item.quantity;

  const deliveryCharge = item.product.freeDelivery
    ? 0
    : 50;

  const serviceCharge = 30;

  const finalTotal =
    productsTotal + deliveryCharge + serviceCharge;

  const codDisabled = item.product.payOnDelivery === false;

  // ✅ PLACE ORDER
  const handlePlaceOrder = async () => {
    if (!name || !phone || !address || !city || !pincode) {
      alert("Please fill all address fields");
      return;
    }

    try {
      const payload = {
        productId,
        quantity: item.quantity,
        address: { name, phone, address, city, pincode },
        amount: finalTotal,
        deliveryCharge,
        serviceCharge,
      };

      // ✅ COD
      if (paymentMode === "cod") {
        await axios.post("/api/order/create-cod", payload);
        alert("✅ Order placed successfully (COD)");
        router.push("/orders");
      }

      // ✅ STRIPE
      if (paymentMode === "stripe") {
        const res = await axios.post(
          "/api/order/online-pay",
          payload
        );
        window.location.href = res.data.url;
      }
    } catch (error: any) {
      console.error("CHECKOUT ERROR:", error);
      alert(
        error?.response?.data?.message ||
          "Checkout failed ❌"
      );
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#0f172a] via-black to-[#020617] flex items-center justify-center px-4 py-10">
      <motion.div
        initial={{ opacity: 0, y: 60 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-4xl bg-white/10 backdrop-blur-xl border border-white/20 rounded-2xl shadow-xl p-6 md:p-10 grid md:grid-cols-2 gap-8"
      >
        {/* ✅ ADDRESS BOX */}
        <div className="space-y-4">
          <h2 className="text-xl font-bold mb-2 text-white">
            Delivery Address
          </h2>

          <input
            className="w-full p-3 rounded bg-black/60 border border-white/20 text-white"
            placeholder="Full Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />

          <input
            className="w-full p-3 rounded bg-black/60 border border-white/20 text-white"
            placeholder="Phone Number"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
          />

          <textarea
            className="w-full p-3 rounded bg-black/60 border border-white/20 text-white"
            placeholder="Full Address"
            rows={3}
            value={address}
            onChange={(e) => setAddress(e.target.value)}
          />

          <div className="grid grid-cols-2 gap-3">
            <input
              className="p-3 rounded bg-black/60 border border-white/20 text-white"
              placeholder="City"
              value={city}
              onChange={(e) => setCity(e.target.value)}
            />
            <input
              className="p-3 rounded bg-black/60 border border-white/20 text-white"
              placeholder="Pincode"
              value={pincode}
              onChange={(e) => setPincode(e.target.value)}
            />
          </div>
        </div>

        {/* ✅ SUMMARY + PAYMENT */}
        <div className="space-y-5">
          <h2 className="text-xl font-bold text-white mb-2">
            Order Summary
          </h2>

          <div className="flex justify-between text-sm text-gray-300">
            <span>Product</span>
            <span>{item.product.title}</span>
          </div>

          <div className="flex justify-between text-sm text-gray-300">
            <span>Products Total</span>
            <span>₹ {productsTotal}</span>
          </div>

          <div className="flex justify-between text-sm text-gray-300">
            <span>Delivery Charges</span>
            <span>₹ {deliveryCharge}</span>
          </div>

          <div className="flex justify-between text-sm text-gray-300">
            <span>Service Charge</span>
            <span>₹ {serviceCharge}</span>
          </div>

          <div className="flex justify-between text-lg font-bold border-t border-white/20 pt-3">
            <span className="text-white">Final Amount</span>
            <span className="text-green-400">
              ₹ {finalTotal}
            </span>
          </div>

          {/* ✅ PAYMENT MODE */}
          <div className="space-y-2">
            <h3 className="font-semibold text-white">
              Payment Method
            </h3>

            <div className="flex gap-3">
              <button
                onClick={() => setPaymentMode("cod")}
                disabled={codDisabled}
                className={`flex-1 py-2 rounded-lg font-semibold transition ${
                  paymentMode === "cod"
                    ? "bg-blue-600"
                    : "bg-white/10"
                } ${
                  codDisabled
                    ? "opacity-40 cursor-not-allowed"
                    : ""
                }`}
              >
                Cash on Delivery
              </button>

              <button
                onClick={() => setPaymentMode("stripe")}
                className={`flex-1 py-2 rounded-lg font-semibold flex items-center justify-center gap-2 transition ${
                  paymentMode === "stripe"
                    ? "bg-blue-600"
                    : "bg-white/10"
                }`}
              >
                <FaStripe size={28} className="bg-white text-blue-600 rounded p-1" />
                Stripe
              </button>
            </div>

            {codDisabled && (
              <p className="text-xs text-red-400">
                ⚠ This product does not support Cash on Delivery.
              </p>
            )}
          </div>

          {/* ✅ ACTION BUTTON */}
          <motion.button
            whileHover={{ scale: 1.04 }}
            whileTap={{ scale: 0.96 }}
            onClick={handlePlaceOrder}
            className="w-full bg-blue-600 hover:bg-blue-700 py-3 rounded-xl font-semibold mt-4"
          >
            {paymentMode === "cod"
              ? "Place Order (COD)"
              : "Proceed to Online Payment"}
          </motion.button>
        </div>
      </motion.div>
    </div>
  );
}
